    "eng_f_speech_hook_prompt": "ਸਵਾਲ, ਹੈਰਾਨ ਕਰਨ ਵਾਲੇ ਤੱਥ ਜਾਂ ਦਲੇਰ ਦਾਅਵੇ ਨਾਲ ਸਰੋਤਿਆਂ ਦਾ ਧਿਆਨ ਖਿੱਚੋ।",
